--
-- The DOMAIN types below are derived from the `value_regex` metadata the
-- upstream Databricks MVM declares on its own columns, so the constraints in
-- this source model are the ones the target model says it expects.
-- =========================================================================

CREATE SCHEMA IF NOT EXISTS common;

COMMENT ON SCHEMA common IS
    'Shared scalar domains, the source-system registry and the cross-system '
    'identity resolution tables. A convenience of this reference '
    'implementation: the real systems of record share no type library.';

-- citext gives case-insensitive natural keys (emails, external codes) without
-- scattering lower() through every unique index.
CREATE EXTENSION IF NOT EXISTS citext;

