-- -------------------------------------------------------------------------
-- Source-system registry.
--
-- The target model's `source_system_code` column is constrained to
-- 'TICKETMASTER|ARCHTICS|SAP_SD|MANUAL|LEAGUE_FEED' -- a five-value list that
-- does not cover the ten systems the same model names as its systems of
-- record. This table is the full registry; the narrower target enum is
-- recorded as a known gap in docs/04-physical-model-target.md.
-- -------------------------------------------------------------------------

CREATE TABLE common.source_system (
    source_system_code  VARCHAR(20)  PRIMARY KEY,
    schema_name         VARCHAR(30)  NOT NULL UNIQUE,
    system_name         VARCHAR(120) NOT NULL,
    vendor_category     VARCHAR(40)  NOT NULL,
    model_tier          CHAR(1)      NOT NULL CHECK (model_tier IN ('A', 'B')),
    extract_pattern     VARCHAR(20)  NOT NULL,
    is_active           BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at          TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ  NOT NULL DEFAULT now()
);

