-- -------------------------------------------------------------------------
-- Cross-system identity resolution.
--
-- The target model carries 1,477 cross-domain foreign keys, all typed BIGINT
-- against a uniform surrogate key. In this tier those references cross a
-- database boundary: a TM/AXS order cannot hold an enforced foreign key into
-- an SAP customer, and the two systems key customers differently (integer
-- identity vs. a 10-character CHAR business key).
--
-- So a cross-system reference is modeled as what it actually is: a business
-- key plus a resolution row. entity_xref maps each system-local key to the
-- canonical surrogate the lakehouse will use, and is the single place the
-- ingestion layer resolves keys.
-- -------------------------------------------------------------------------

CREATE TABLE common.canonical_entity (
    entity_type      VARCHAR(40)  PRIMARY KEY,
    target_domain    VARCHAR(20)  NOT NULL,
    target_table     VARCHAR(60)  NOT NULL,
    target_key       VARCHAR(60)  NOT NULL,
    description      TEXT,
    UNIQUE (target_domain, target_table)
);

COMMENT ON TABLE common.canonical_entity IS
    'The business entities that exist in more than one source system and so '
    'need identity resolution before load. One row per target master table.';

CREATE TABLE common.entity_xref (
    entity_xref_id     BIGINT       GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    entity_type        VARCHAR(40)  NOT NULL REFERENCES common.canonical_entity(entity_type),
    source_system_code VARCHAR(20)  NOT NULL REFERENCES common.source_system(source_system_code),
    source_key         VARCHAR(120) NOT NULL,
    canonical_id       BIGINT       NOT NULL,
    match_method       VARCHAR(20)  NOT NULL
        CHECK (match_method IN ('deterministic', 'probabilistic', 'manual', 'survivorship')),
    match_confidence   NUMERIC(5,4)
        CHECK (match_confidence IS NULL OR match_confidence BETWEEN 0 AND 1),
    is_survivor        BOOLEAN      NOT NULL DEFAULT FALSE,
    valid_from         TIMESTAMPTZ  NOT NULL DEFAULT now(),
    valid_to           TIMESTAMPTZ,
    created_at         TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ  NOT NULL DEFAULT now(),
    -- One live mapping per (entity, system, source key).
    UNIQUE (entity_type, source_system_code, source_key, valid_from)
);

CREATE INDEX ix_entity_xref_canonical
    ON common.entity_xref (entity_type, canonical_id);
CREATE INDEX ix_entity_xref_lookup
    ON common.entity_xref (entity_type, source_system_code, source_key)
    WHERE valid_to IS NULL;

COMMENT ON COLUMN common.entity_xref.is_survivor IS
    'Marks the record that wins survivorship for this canonical_id, i.e. the '
    'system whose attribute values are kept when two sources disagree.';

