-- -------------------------------------------------------------------------
-- Shared audit trigger. Every table in every system schema carries
-- created_at / updated_at; this keeps updated_at honest without ten copies.
-- -------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION common.touch_updated_at()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION common.touch_updated_at() IS
    'BEFORE UPDATE trigger function. Each system schema attaches it in 70_audit.sql.';

